{
  "root_causes": [
    {
      "service": "rate",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT metric, attr_k8s_pod_name AS pod, CAST(min(time) AS VARCHAR) AS t0, CAST(max(time) AS VARCHAR) AS t1, count(*) AS n, avg(value) AS v FROM abnormal_metrics WHERE metric IN ('k8s.deployment.available','k8s.deployment.desired','k8s.pod.phase','k8s.container.ready') AND (attr_k8s_deployment_name='rate' OR attr_k8s_pod_name LIKE 'rate-%') GROUP BY 1,2 ORDER BY 1,2",
          "claim": "The rate pod reports container not ready and deployment available 0 for the whole abnormal window, while desired stays 1."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, attr_k8s_pod_name AS pod, count(*) AS n FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'rate-66f986cc46%' GROUP BY 1,2 ORDER BY 1",
          "claim": "Only readiness, restart, phase and deployment metrics appear for the rate pod in the abnormal period; its CPU and memory series are absent."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) AS n FROM abnormal_traces WHERE service_name='rate' GROUP BY 1,2,3",
          "claim": "The rate service emits no spans in the abnormal period, though it emitted about 529 GetRates server spans in the normal period."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "rate",
      "to": "search",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) AS n, avg(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS err_share FROM abnormal_traces WHERE span_name IN ('rate.Rate/GetRates') AND service_name='search' GROUP BY 1,2,3",
          "claim": "Search's client calls to rate.Rate/GetRates fail with about 99% error share in the abnormal period, versus 0% in normal."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, message, count(*) AS n FROM abnormal_logs WHERE service_name='search' AND level='ERROR' GROUP BY 1,2",
          "claim": "Search logs 'Failed to get rates from rate service' about 327 times as ERROR in the abnormal period."
        }
      ]
    },
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_span_kind, count(*) AS n, avg(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS err_share FROM abnormal_traces WHERE span_name IN ('search.Search/Nearby','HTTP /hotels') GROUP BY 1,2,3",
          "claim": "Search Nearby server spans fail at about 99%, and frontend's /hotels HTTP spans fail at 100% in the abnormal period."
        },
        {
          "kind": "log",
          "sql": "SELECT service_name, message, level, count(*) AS n FROM abnormal_logs WHERE service_name='frontend' AND level='ERROR' GROUP BY 1,2,3",
          "claim": "Frontend logs 'Search service failed' as ERROR about 324 times in the abnormal period, against none in normal."
        }
      ]
    }
  ]
}
